export function materializeShareSnapshot(root, preparation, defaults = {}) {
  const project = readProjectShare(root)
  if (!project) return null
  if (!preparation) fail('Run game/sharing/prepare before building a project that has game-sharing.json')
  const assets = {}, bytes = {}
  for (const purpose of ['og', 'favicon']) {
    const sourcePath = project.assets[purpose]
    if (!sourcePath) continue
    const image = projectAsset(root, sourcePath)
    assets[purpose] = image.release
    bytes[purpose] = image.bytes
  }
  const snapshot = parseShareSnapshot({ schemaVersion: 2, publicationOrigin: preparation.publicationOrigin,
    title: project.title ?? defaults?.title ?? projectTitle(root), description: project.description ?? defaults?.description ?? projectDescription(root), defaultCaptions: project.defaultCaptions, assets })
  return { snapshot, bytes }
}

export function addExportedFavicon(sharing, exportRoot) {
  if (!sharing || sharing.snapshot.assets.favicon) return sharing
  let bytes
  try { bytes = regularFile(exportRoot, ['index.icon.png'], MAX_SHARE_IMAGE_BYTES) }
  catch (error) { if (error.code === 'ENOENT') return sharing; throw error }
  if (bytes.length < 33 || !bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) ||
      bytes.readUInt32BE(8) !== 13 || bytes.toString('ascii', 12, 16) !== 'IHDR') fail('Game exported favicon is not a valid PNG')
  const width = bytes.readUInt32BE(16), height = bytes.readUInt32BE(20)
  if (!width || !height || width * height > 16 * 1024 * 1024) fail('Game exported favicon dimensions are invalid')
  const hash = digest(bytes)
  return {
    snapshot: parseShareSnapshot({ ...sharing.snapshot, assets: { ...sharing.snapshot.assets,
      favicon: { digest: hash, path: `share/${hash.slice(7)}.png`, mime: 'image/png', width, height, sizeBytes: bytes.length } } }),
    bytes: { ...sharing.bytes, favicon: bytes },
  }
}

