export function assembleShareSite(_root, site, materialized, options) {
  if (!materialized) return
  const snapshot = parseShareSnapshot(materialized.snapshot ?? materialized), realSite = realpathSync(site), shared = directory(realSite, 'share')
  for (const purpose of ['og', 'favicon']) {
    const expected = snapshot.assets[purpose]
    if (expected) atomicWrite(shared, expected.digest.slice(7) + '.png', verifyShareImage(materialized.bytes?.[purpose], expected))
  }
  atomicWrite(realSite, GAME_SHARING_FILE, canonicalShareSnapshot(snapshot))
  if (!options?.preserveHtml) atomicWrite(realSite, 'index.html', applyShareHtml(regularFile(site, ['index.html'], 8 * 1024 * 1024).toString('utf8'), snapshot, options))
}
export function verifyShareSite(root, site) {
  const published = readPreparedShare(site)
  if (!published) return null
  for (const expected of Object.values(published.assets)) verifyShareImage(regularFile(site, expected.path.split('/'), MAX_SHARE_IMAGE_BYTES), expected)
  const html = regularFile(site, ['index.html'], 8 * 1024 * 1024).toString('utf8')
  if (applyShareHtml(html, published) !== html) fail('Game sharing HTML does not match its checkpoint metadata')
  if (published.schemaVersion === 1) {
    const legacy = readPreparedShare(root)
    if (!legacy || canonicalShareSnapshot(legacy) !== canonicalShareSnapshot(published)) fail('Legacy Game sharing snapshot is incomplete')
  }
  return published
}

/** Shared by the portable Web build hook and the immutable browser snapshot builder. */
export function assembleThreejsShareSite(projectDir, outputDirectory, preparation) {
  const root = realpathSync(projectDir), project = readProjectShare(root)
  if (!project) return null
  if (typeof outputDirectory !== 'string' || !/^[\w./-]+$/.test(outputDirectory) ||
      outputDirectory.split('/').some(part => !part || part === '.' || part === '..')) fail('Sharing output must be a project directory')
  let output = root
  for (const part of outputDirectory.split('/')) {
    output = join(output, part)
    const stat = lstatSync(output)
    if (stat.isSymbolicLink() || !stat.isDirectory()) fail('Sharing output must be a project directory')
  }
  const html = regularFile(output, ['index.html'], 8 * 1024 * 1024).toString('utf8')
  const pkg = JSON.parse(regularFile(root, ['package.json'], 1024 * 1024).toString('utf8'))
  const sharing = materializeShareSnapshot(root, preparation, {
    title: preparation?.projectTitle?.trim() || (typeof pkg.name === 'string' ? pkg.name.trim().slice(0, 120) : '') || 'Game',
    description: typeof pkg.description === 'string' ? pkg.description.slice(0, 1000) : '',
    ...shareHtmlDefaults(html),
  })
  // Without a cover, change only explicit metadata. Keep the author's other
  // tags (including externally hosted OG images) intact.
  const fields = project.assets.og ? undefined : [
    ...(project.title !== undefined ? ['title', 'og:title', 'twitter:title'] : []),
    ...(project.description !== undefined ? ['description', 'og:description', 'twitter:description'] : []),
    ...(project.assets.favicon ? ['favicon'] : []),
  ]
  assembleShareSite(root, output, sharing, { preserveUnconfiguredFavicon: true, fields, preserveHtml: fields?.length === 0 })
  return sharing.snapshot
}
